package com.gameaggregator.versionservice.api;import static org.assertj.core.api.Assertions.assertThat;import java.util.regex.Pattern;import org.junit.jupiter.api.Test;class SemanticVersionTest{@Test void acceptsSemanticVersions(){var p=Pattern.compile(VersionDtos.SEMVER);assertThat(p.matcher("1.2.3").matches()).isTrue();assertThat(p.matcher("2.0.0-beta.1+build.9").matches()).isTrue();}@Test void rejectsInvalidVersions(){var p=Pattern.compile(VersionDtos.SEMVER);assertThat(p.matcher("v1").matches()).isFalse();assertThat(p.matcher("1.2").matches()).isFalse();assertThat(p.matcher("01.2.3").matches()).isFalse();}}